        self.operators: set[str] = set()
        self.idem: dict[str, dict] = {}        # scope key -> record
        self.seq = 0
        self.last_ts = 0.0

    # -- clock and sequencing ------------------------------------------------
    def now(self) -> float:
        ts = max(time.time(), self.last_ts)
        self.last_ts = ts
        return ts
